// @domain: awareness
//! The v1 requirements (#4478 "What v1 taught us"), as tests every generated API runs.
//! They drive the real write path against an in-memory store, so each one fails if the
//! rule it guards is taken out. Generated by athena-gen — DO NOT EDIT; change the generator.

use crate::auth::{self, Caller};
use crate::model::{ClassDef, CLASSES, NS};
use crate::rules::Cell;
use crate::store::{iri, name_of, Row, RowStore};
use crate::{write, Ctx};
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::sync::Mutex;

/// subject → (graph, type, field → values as written: "<iri>" or "literal")
#[derive(Default)]
struct Mem(Mutex<BTreeMap<String, (String, String, BTreeMap<String, Vec<String>>)>>);

impl Mem {
    fn put(&self, graph: &str, subject: &str, ty: &str, fields: &[(&str, &[&str])]) {
        let f = fields.iter().map(|(k, v)| (k.to_string(), v.iter().map(|s| s.to_string()).collect())).collect();
        self.0.lock().unwrap().insert(subject.into(), (graph.into(), ty.into(), f));
    }
    fn values(&self, subject: &str, field: &str) -> Vec<String> {
        self.0.lock().unwrap().get(subject).and_then(|r| r.2.get(field).cloned()).unwrap_or_default()
    }
}

fn local(v: &str) -> String {
    v.trim_start_matches('<').trim_end_matches('>').rsplit(['#', '/']).next().unwrap_or(v).to_string()
}

impl RowStore for Mem {
    fn list(&self, class: &ClassDef, _l: usize, _o: usize) -> Result<(Vec<Row>, usize), String> {
        let subjects: Vec<String> = self.0.lock().unwrap().iter().filter(|(_, r)| r.1 == class.name).map(|(s, _)| s.clone()).collect();
        let rows: Vec<Row> = subjects.iter().filter_map(|s| self.get(class, &name_of(class, s)).ok().flatten()).collect();
        let n = rows.len();
        Ok((rows, n))
    }
    fn get(&self, class: &ClassDef, name: &str) -> Result<Option<Row>, String> {
        let m = self.0.lock().unwrap();
        let Some((_, ty, f)) = m.get(&iri(class, name)) else { return Ok(None) };
        if ty != class.name { return Ok(None); }
        let mut row = Row::new();
        row.insert("name".into(), json!(name));
        row.insert("label".into(), json!(f.get("label").and_then(|v| v.first()).cloned().unwrap_or_default()));
        row.insert("status".into(), json!(""));
        for fd in class.fields {
            let mut v: Vec<String> = f.get(fd.name).cloned().unwrap_or_default().iter().map(|x| local(x)).collect();
            v.sort();
            row.insert(fd.name.into(), if fd.many { json!(v) } else { json!(v.into_iter().next().unwrap_or_default()) });
        }
        Ok(Some(row))
    }
    fn exists(&self, iri: &str) -> Result<bool, String> {
        Ok(self.0.lock().unwrap().contains_key(iri))
    }
    fn version_count(&self, of_row: &str) -> Result<usize, String> {
        Ok(self.0.lock().unwrap().values().filter(|r| r.2.get("ofRow").is_some_and(|v| v.contains(&of_row.to_string()))).count())
    }
    fn write(&self, graph: &str, subject: &str, type_of: Option<&str>, fields: &[(String, Vec<Cell>)], whole: bool) -> Result<(), String> {
        let mut m = self.0.lock().unwrap();
        let e = m.entry(subject.to_string()).or_insert_with(|| (graph.to_string(), String::new(), BTreeMap::new()));
        if whole { e.2.clear(); }
        if let Some(t) = type_of { e.1 = t.to_string(); }
        for (k, cells) in fields {
            let vals = cells.iter().map(|c| match c { Cell::Link(i) => format!("<{i}>"), Cell::Literal(v, _) => v.clone() }).collect();
            e.2.insert(k.clone(), vals); // every stored value of the field goes, whatever its IRI
        }
        Ok(())
    }
    fn delete(&self, _graph: &str, subject: &str) -> Result<(), String> {
        self.0.lock().unwrap().remove(subject);
        Ok(())
    }
    // owner only: the grant rules are proven on the real SPARQL store (embedded_tests)
    fn list_seen_by(&self, class: &ClassDef, l: usize, o: usize, viewer: &str) -> Result<(Vec<Row>, usize), String> {
        let (rows, _) = self.list(class, l, o)?;
        let mine: Vec<Row> = rows.into_iter().filter(|r| r.get("ownedBy").and_then(|v| v.as_str()).is_some_and(|v| viewer.ends_with(v))).collect();
        let n = mine.len();
        Ok((mine, n))
    }
    fn get_seen_by(&self, class: &ClassDef, name: &str, viewer: &str) -> Result<Option<Row>, String> {
        Ok(self.get(class, name)?.filter(|r| r.get("ownedBy").and_then(|v| v.as_str()).is_some_and(|v| viewer.ends_with(v))))
    }
    // the filter itself is proven on the real SPARQL store (embedded_tests)
    fn list_where(&self, class: &ClassDef, l: usize, o: usize, viewer: Option<&str>, _w: &crate::store::Where) -> Result<(Vec<Row>, usize), String> {
        match viewer { Some(v) => self.list_seen_by(class, l, o, v), None => self.list(class, l, o) }
    }
}

fn class_with_link() -> &'static ClassDef {
    CLASSES.iter().find(|c| c.fields.iter().any(|f| f.link && f.name != "ownedBy")).expect("a class with a link field")
}

fn ctx(store: &Mem) -> Ctx<'_> {
    let who = Box::leak(Box::new(auth::build("http://127.0.0.1:9/", |_| None)));
    Ctx { store, who, events: String::new(), reads_public: true }
}

fn caller(name: &str, scopes: &[&str]) -> Caller {
    Caller { principal: name.into(), web_id: format!("https://id.example/{name}"), scopes: scopes.iter().map(|s| s.to_string()).collect() }
}

/// A row of the class, owned by `owner`, with every required field filled and every
/// link pointing at a row that exists.
fn seed(store: &Mem, class: &ClassDef, name: &str, owner: &str) {
    store.put("urn:test:people", &format!("{NS}principal-{owner}"), "Principal", &[]);
    let mut fields: Vec<(String, Vec<String>)> = vec![("ownedBy".into(), vec![format!("<{NS}principal-{owner}>")])];
    for f in class.fields.iter().filter(|f| f.name != "ownedBy") {
        let v = if f.link {
            let t = format!("{NS}target-{}", f.name);
            store.put("urn:test:targets", &t, "Target", &[]);
            format!("<{t}>")
        } else {
            f.allowed.first().map(|a| a.to_string()).unwrap_or_else(|| "2026-10-10T00:00:00Z".into())
        };
        fields.push((f.name.into(), vec![v]));
    }
    let borrowed: Vec<(&str, Vec<&str>)> = fields.iter().map(|(k, v)| (k.as_str(), v.iter().map(String::as_str).collect())).collect();
    let refs: Vec<(&str, &[&str])> = borrowed.iter().map(|(k, v)| (*k, v.as_slice())).collect();
    store.put(class.graph, &iri(class, name), class.name, &refs);
}

#[test]
fn req1_patch_changes_named_fields_only_and_null_removes_one() {
    let store = Mem::default();
    let c = class_with_link();
    seed(&store, c, "r1", "wren");
    let opt = c.fields.iter().find(|f| !f.required && f.name != "ownedBy");
    let keep = c.fields.iter().find(|f| f.required && f.name != "ownedBy").expect("a required field");
    let before = store.values(&iri(c, "r1"), keep.name);
    if let Some(opt) = opt {
        let (code, out) = write(&ctx(&store), &caller("wren", &[]), "PATCH", c, Some("r1"), &json!({ opt.name: Value::Null }).to_string());
        assert_eq!(code, 200, "{out}");
        assert!(store.values(&iri(c, "r1"), opt.name).is_empty(), "null must remove the field");
    }
    assert_eq!(store.values(&iri(c, "r1"), keep.name), before, "a field the patch did not name must not change");
    assert_eq!(store.0.lock().unwrap()[&iri(c, "r1")].1, c.name, "the type is never touched");
}

#[test]
fn req2_changing_a_link_removes_the_value_the_store_holds_even_a_wrong_kind_one() {
    let store = Mem::default();
    let c = class_with_link();
    let f = c.fields.iter().find(|f| f.link && f.name != "ownedBy").unwrap();
    seed(&store, c, "r2", "wren");
    store.0.lock().unwrap().get_mut(&iri(c, "r2")).unwrap().2.insert(f.name.into(), vec![format!("<{NS}Proving>")]);
    store.put("urn:test:targets", &format!("{NS}target-new"), "Target", &[]);
    let (code, out) = write(&ctx(&store), &caller("wren", &[]), "PATCH", c, Some("r2"), &json!({ f.name: "target-new" }).to_string());
    assert_eq!(code, 200, "{out}");
    assert_eq!(store.values(&iri(c, "r2"), f.name), [format!("<{NS}target-new>")], "the old c:Proving must be gone, not kept beside");
}

#[test]
fn req3_get_returns_every_value_of_a_many_link() {
    let store = Mem::default();
    let Some((c, f)) = CLASSES.iter().find_map(|c| c.fields.iter().find(|f| f.link && f.many).map(|f| (c, f))) else { return };
    seed(&store, c, "r3", "wren");
    store.0.lock().unwrap().get_mut(&iri(c, "r3")).unwrap().2.insert(f.name.into(), vec![format!("<{NS}a>"), format!("<{NS}b>")]);
    let row = store.get(c, "r3").unwrap().unwrap();
    assert_eq!(row[f.name], json!(["a", "b"]));
}

#[test]
fn req4_a_link_to_nothing_is_refused_and_nothing_is_written() {
    let store = Mem::default();
    let c = class_with_link();
    let f = c.fields.iter().find(|f| f.link && f.name != "ownedBy").unwrap();
    seed(&store, c, "r4", "wren");
    let before = store.values(&iri(c, "r4"), f.name);
    let (code, out) = write(&ctx(&store), &caller("wren", &[]), "PATCH", c, Some("r4"), &json!({ f.name: "nobody-here" }).to_string());
    assert_eq!((code, out["error"].as_str()), (422, Some("unknown-target")), "{out}");
    assert_eq!(store.values(&iri(c, "r4"), f.name), before, "a refused write changes nothing");
}

#[test]
fn req5_a_row_with_no_owner_opens_only_to_a_write_permission_on_its_graph() {
    let store = Mem::default();
    let c = class_with_link();
    seed(&store, c, "r5", "wren");
    store.0.lock().unwrap().get_mut(&iri(c, "r5")).unwrap().2.remove("ownedBy");
    let opt = c.fields.iter().find(|f| !f.link && !f.allowed.is_empty()).or_else(|| c.fields.iter().find(|f| !f.link)).unwrap();
    let body = json!({ opt.name: opt.allowed.first().copied().unwrap_or("2026-10-11T00:00:00Z") }).to_string();
    let (code, out) = write(&ctx(&store), &caller("kade", &[]), "PATCH", c, Some("r5"), &body);
    assert_eq!((code, out["error"].as_str()), (403, Some("no-permission")), "{out}");
    let (code, out) = write(&ctx(&store), &caller("kade", &[c.graph]), "PATCH", c, Some("r5"), &body);
    assert_eq!(code, 200, "{out}");
}

