#[test]
fn req6_the_name_you_write_is_the_name_you_read() {
    for c in CLASSES {
        for name in ["plain", "with-dash", "gate-demo", &format!("{}-x", c.kind)] {
            assert_eq!(name_of(c, &iri(c, name)), name, "{} {name}", c.name);
        }
    }
    let store = Mem::default();
    let c = class_with_link();
    let (code, out) = write(&ctx(&store), &caller("wren", &[]), "POST", c, None, &json!({ "name": "demo_gate" }).to_string());
    assert_eq!((code, out["error"].as_str()), (422, Some("bad-name")), "a name that cannot round-trip is refused, never rewritten: {out}");
}

#[test]
fn every_change_keeps_the_version_it_displaces() {
    let store = Mem::default();
    let c = class_with_link();
    seed(&store, c, "rv", "wren");
    let f = c.fields.iter().find(|f| !f.link).unwrap();
    let body = json!({ f.name: f.allowed.last().copied().unwrap_or("2026-10-12T00:00:00Z") }).to_string();
    let (code, _) = write(&ctx(&store), &caller("wren", &[]), "PATCH", c, Some("rv"), &body);
    assert_eq!(code, 200);
    assert_eq!(store.version_count(&format!("{}/rv", c.plural)).unwrap(), 1);
}

#[test]
fn req2_store_side_a_field_change_deletes_every_stored_value_by_wildcard() {
    let u = crate::store::write_update("urn:g", "https://x#s", None, &[("f".into(), vec![Cell::Link(format!("{NS}new"))])], false);
    assert!(u.contains(&format!("DELETE WHERE {{ GRAPH <urn:g> {{ <https://x#s> <{NS}f> ?o }} }}")), "{u}");
    assert!(u.find("DELETE").unwrap() < u.find("INSERT").unwrap(), "delete first, then insert: {u}");
}

// #4524 — a private product (the default) refuses a read that names no caller.
#[test]
fn an_unsigned_read_of_a_private_product_is_refused() {
    let store = Mem(Mutex::new(BTreeMap::new()));
    let who = Box::leak(Box::new(auth::build("http://127.0.0.1:9/", |_| None)));
    let private = Ctx { store: &store, who, events: String::new(), reads_public: false };
    let c = CLASSES.first().expect("a class");
    let (code, out) = crate::route(&private, "GET", &format!("/{}/{}/{}", crate::model::PRODUCT, c.domain, c.segment), None, "");
    assert_eq!(code, 401, "{out}");
    // negative proof: the same read on a public product answers
    let public = Ctx { store: &store, who, events: String::new(), reads_public: true };
    let (code, _) = crate::route(&public, "GET", &format!("/{}/{}/{}", crate::model::PRODUCT, c.domain, c.segment), None, "");
    assert_eq!(code, 200);
}

// #4742 — Jeff 10-25: "the top level route is /pulse and each associated domain is a child route".
#[test]
fn every_collection_answers_under_the_product_route() {
    let store = Mem(Mutex::new(BTreeMap::new()));
    let who = Box::leak(Box::new(auth::build("http://127.0.0.1:9/", |_| None)));
    let public = Ctx { store: &store, who, events: String::new(), reads_public: true };
    for c in CLASSES {
        let (code, out) = crate::route(&public, "GET", &format!("/{}/{}/{}", crate::model::PRODUCT, c.domain, c.segment), None, "");
        assert_eq!(code, 200, "/{}/{}/{}: {out}", crate::model::PRODUCT, c.domain, c.segment);
    }
}

